changeSet.sql:
INSERT INTO public.relation_definition (fk_source_field_id, fk_target_field_id, kind, is_symmetric, is_hierarchical, fk_qualifier_field_id)
SELECT -328, -329, 'COMPLEX', false, false, -328
WHERE NOT EXISTS (SELECT 1 FROM public.relation_definition WHERE fk_source_field_id = -328);
INSERT INTO public.relation_definition (fk_source_field_id, fk_target_field_id, kind, is_symmetric, is_hierarchical, fk_qualifier_field_id)
SELECT -330, -330, 'COMPLEX', true, false, -330
WHERE NOT EXISTS (SELECT 1 FROM public.relation_definition WHERE fk_source_field_id = -330);

DO $do$
DECLARE
    v_order     bigint := (SELECT relation_definition_id FROM public.relation_definition WHERE fk_source_field_id = -328);
    v_synchrony bigint := (SELECT relation_definition_id FROM public.relation_definition WHERE fk_source_field_id = -330);
    v_rule      bigint;
    v_def       bigint;
    v_other     bigint;
BEGIN
    FOREACH v_def IN ARRAY ARRAY[v_order, v_synchrony] LOOP
        v_other := CASE WHEN v_def = v_order THEN v_synchrony ELSE v_order END;
        SELECT relation_rule_id INTO v_rule FROM public.relation_rule
        WHERE fk_relation_definition_id = v_def AND fk_institution_id IS NULL;
        IF v_rule IS NULL THEN
            INSERT INTO public.relation_rule (fk_relation_definition_id, no_cycle)
            VALUES (v_def, v_def = v_order) RETURNING relation_rule_id INTO v_rule;
            INSERT INTO public.relation_rule_kind (fk_relation_rule_id, side, kind)
            VALUES (v_rule, 'SOURCE', 'RECORDING_UNIT'), (v_rule, 'TARGET', 'RECORDING_UNIT');
            INSERT INTO public.relation_rule_exclusion (fk_relation_rule_id, fk_excluded_definition_id)
            VALUES (v_rule, v_other);
        END IF;
    END LOOP;
END
$do$;

CREATE OR REPLACE FUNCTION public.tmp_siamois_strati_norm(p_label text) RETURNS text LANGUAGE sql IMMUTABLE AS $f$ SELECT lower(public.unaccent(btrim(p_label))) $f$;
CREATE OR REPLACE FUNCTION public.tmp_siamois_strati_concepts() RETURNS TABLE (concept_id bigint, vocabulary_id bigint, branch text, grp text, label text) LANGUAGE sql STABLE AS $f$ WITH RECURSIVE branch(top, concept_id, depth) AS ( SELECT cfc.field_code, cfc.fk_concept_id, 0 FROM public.concept_field_config cfc WHERE cfc.field_code IN ('SIARU.STRATI', 'SIARU.STRATI.ANTERIOR', 'SIARU.STRATI.POSTERIOR', 'SIARU.STRATI.SYNCHRONOUS') UNION SELECT b.top, h.fk_child_concept_id, b.depth + 1 FROM branch b JOIN public.concept_hierarchy h ON h.fk_parent_concept_id = b.concept_id WHERE b.depth < 10 ) SELECT DISTINCT b.concept_id, c.fk_vocabulary_id, b.top, CASE b.top WHEN 'SIARU.STRATI' THEN 'legacy' WHEN 'SIARU.STRATI.SYNCHRONOUS' THEN 'sync' ELSE 'order' END, (SELECT public.tmp_siamois_strati_norm(l.label) FROM public.concept_label l WHERE l.fk_concept_id = b.concept_id AND l.lang_code = 'fr' ORDER BY l.label_type, l.label LIMIT 1) FROM branch b JOIN public.concept c ON c.concept_id = b.concept_id WHERE b.depth > 0 $f$;
CREATE OR REPLACE FUNCTION public.tmp_siamois_strati_pairs() RETURNS TABLE (posterior_label text, anterior_label text) LANGUAGE sql IMMUTABLE AS $f$ VALUES ('coupe', 'est coupee par'), ('recouvre', 'est recouverte par'), ('s''appuie sur', 'est appuyee par'), ('comble', 'est comblee par'), ('sur', 'sous') $f$;

DO $do$ DECLARE v_order bigint := (SELECT relation_definition_id FROM public.relation_definition WHERE fk_source_field_id = -328); v_synchrony bigint := (SELECT relation_definition_id FROM public.relation_definition WHERE fk_source_field_id = -330); v_rule bigint := (SELECT relation_rule_id FROM public.relation_rule WHERE fk_relation_definition_id = v_order AND fk_institution_id IS NULL); v_total integer; v_order_count integer; v_sync_count integer; BEGIN CREATE TEMPORARY TABLE tmp_strati ON COMMIT DROP AS SELECT r.fk_recording_unit_1_id AS anterior, r.fk_recording_unit_2_id AS posterior, COALESCE(r.asynchronous, true) AS asynchronous, COALESCE(r.uncertain, false) AS uncertain, a.fk_action_unit_id AS project, b.fk_action_unit_id AS other_project, r.fk_relationship_concept_id AS concept, (SELECT public.tmp_siamois_strati_norm(l.label) FROM public.concept_label l WHERE l.fk_concept_id = r.fk_relationship_concept_id AND l.lang_code = 'fr' ORDER BY l.label_type, l.label LIMIT 1) AS label FROM public.stratigraphic_relationship r JOIN public.recording_unit a ON a.recording_unit_id = r.fk_recording_unit_1_id JOIN public.recording_unit b ON b.recording_unit_id = r.fk_recording_unit_2_id;
-- The links that are not taken over today: hierarchy-like concepts, or units of two projects. DELETE FROM tmp_strati WHERE label IN ('regroupe', 'est regroupee dans', 'englobe', 'est englobee par') OR project IS NULL OR project IS DISTINCT FROM other_project;
INSERT INTO public.relation_link (fk_relation_definition_id, fk_action_unit_id, source_kind, source_id, target_kind, target_id, fk_qualifier_concept_id, uncertain, simple) SELECT v_order, t.project, 'RECORDING_UNIT', t.posterior, 'RECORDING_UNIT', t.anterior, CASE WHEN t.label IN ('anterieur a', 'posterieur a') THEN NULL ELSE COALESCE((SELECT m.fk_concept_id FROM public.relation_rule_mirror_concept m WHERE m.fk_relation_rule_id = v_rule AND m.fk_mirror_concept_id = t.concept), t.concept) END, t.uncertain, false FROM tmp_strati t WHERE t.asynchronous AND NOT EXISTS (SELECT 1 FROM public.relation_link l WHERE l.fk_relation_definition_id = v_order AND l.source_kind = 'RECORDING_UNIT' AND l.source_id = t.posterior AND l.target_kind = 'RECORDING_UNIT' AND l.target_id = t.anterior); GET DIAGNOSTICS v_order_count = ROW_COUNT;
INSERT INTO public.relation_link (fk_relation_definition_id, fk_action_unit_id, source_kind, source_id, target_kind, target_id, fk_qualifier_concept_id, uncertain, simple) SELECT v_synchrony, t.project, 'RECORDING_UNIT', LEAST(t.anterior, t.posterior), 'RECORDING_UNIT', GREATEST(t.anterior, t.posterior), CASE WHEN t.label = 'synchrone avec' THEN NULL ELSE t.concept END, t.uncertain, false FROM tmp_strati t WHERE NOT t.asynchronous AND NOT EXISTS (SELECT 1 FROM public.relation_link l WHERE l.fk_relation_definition_id = v_synchrony AND l.source_kind = 'RECORDING_UNIT' AND l.source_id = LEAST(t.anterior, t.posterior) AND l.target_kind = 'RECORDING_UNIT' AND l.target_id = GREATEST(t.anterior, t.posterior)); GET DIAGNOSTICS v_sync_count = ROW_COUNT;
SELECT count(*) INTO v_total FROM public.stratigraphic_relationship; RAISE NOTICE 'Stratigraphy takeover: % old relationships, % order links and % synchrony links written, % left in the old table', v_total, v_order_count, v_sync_count, v_total - (SELECT count(*) FROM tmp_strati); END $do$;

DO $do$
DECLARE
    v_column text;
    v_constraint text;
BEGIN
    FOREACH v_column IN ARRAY ARRAY['fk_recording_unit_1_id', 'fk_recording_unit_2_id'] LOOP
        FOR v_constraint IN
            SELECT c.conname FROM pg_constraint c
            JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = ANY (c.conkey)
            WHERE c.conrelid = 'public.stratigraphic_relationship'::regclass AND c.contype = 'f'
              AND a.attname = v_column
        LOOP
            EXECUTE format('ALTER TABLE public.stratigraphic_relationship DROP CONSTRAINT %I', v_constraint);
        END LOOP;
        EXECUTE format('ALTER TABLE public.stratigraphic_relationship ADD CONSTRAINT %I FOREIGN KEY (%I) '
                       'REFERENCES public.recording_unit (recording_unit_id) ON DELETE CASCADE',
                       'fk_stratigraphic_relationship_' || replace(v_column, 'fk_', ''), v_column);
    END LOOP;
END
$do$;

DROP FUNCTION IF EXISTS public.tmp_siamois_strati_pairs();
DROP FUNCTION IF EXISTS public.tmp_siamois_strati_concepts();
DROP FUNCTION IF EXISTS public.tmp_siamois_strati_norm(text);
